export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  content: string;
  html: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

import { promises as fs } from 'fs';
import * as path from 'path';
import { marked } from 'marked';
import matter from 'gray-matter';

import type { BuildOptions, Page } from './types';

function slugify(name: string): string {
  return name
    .replace(/\.md$/i, '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function normalizeTags(tags: unknown): string[] {
  if (Array.isArray(tags)) {
    return tags.map((tag) => String(tag)).filter((tag) => tag.length > 0);
  }
  if (typeof tags === 'string') {
    return tags
      .split(',')
      .map((tag) => tag.trim())
      .filter((tag) => tag.length > 0);
  }
  return [];
}

export function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

export function pagePath(page: Page): string {
  return `${page.slug}.html`;
}

export async function listMarkdownFiles(contentDir: string): Promise<string[]> {
  const entries = await fs.readdir(contentDir, { withFileTypes: true });
  const files: string[] = [];
  for (const entry of entries) {
    const fullPath = path.join(contentDir, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await listMarkdownFiles(fullPath)));
    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
      files.push(fullPath);
    }
  }
  return files.sort();
}

export async function parseMarkdownFile(filePath: string): Promise<Page> {
  const raw = await fs.readFile(filePath, 'utf8');
  const parsed = matter(raw);
  const frontmatter = parsed.data ?? {};
  const baseName = path.basename(filePath);
  const slug = slugify(baseName);
  const title =
    typeof frontmatter.title === 'string' && frontmatter.title.trim().length > 0
      ? frontmatter.title.trim()
      : baseName.replace(/\.md$/i, '');
  const date = typeof frontmatter.date === 'string' ? frontmatter.date : undefined;
  const html = await marked.parse(parsed.content);
  return {
    slug,
    title,
    date,
    tags: normalizeTags(frontmatter.tags),
    content: parsed.content,
    html,
  };
}

export function renderPage(page: Page): string {
  const dateHtml = page.date
    ? `<p class="date"><time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time></p>`
    : '';
  const tagsHtml =
    page.tags.length > 0
      ? `<p class="tags">${page.tags
          .map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`)
          .join(' ')}</p>`
      : '';
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(page.title)}</title>
</head>
<body>
  <header>
    <nav><a href="index.html">Home</a></nav>
    <h1>${escapeHtml(page.title)}</h1>
    ${dateHtml}
  </header>
  <main>
${page.html}
${tagsHtml}
  </main>
</body>
</html>
`;
}

export function renderIndex(pages: Page[]): string {
  const items = [...pages]
    .sort((a, b) => (b.date ?? '').localeCompare(a.date ?? ''))
    .map((page) => {
      const date = page.date
        ? ` <time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>`
        : '';
      const tags =
        page.tags.length > 0
          ? ` <span class="tags">${page.tags.map((tag) => escapeHtml(tag)).join(', ')}</span>`
          : '';
      return `    <li><a href="${pagePath(page)}">${escapeHtml(page.title)}</a>${date}${tags}</li>`;
    })
    .join('\n');
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Index</title>
</head>
<body>
  <header>
    <h1>Index</h1>
  </header>
  <main>
    <ul>
${items}
    </ul>
  </main>
</body>
</html>
`;
}

export async function build(options: BuildOptions): Promise<Page[]> {
  const files = await listMarkdownFiles(options.contentDir);
  const pages: Page[] = [];
  for (const file of files) {
    pages.push(await parseMarkdownFile(file));
  }
  await fs.mkdir(options.outputDir, { recursive: true });
  await Promise.all([
    fs.writeFile(path.join(options.outputDir, 'index.html'), renderIndex(pages), 'utf8'),
    ...pages.map((page) =>
      fs.writeFile(path.join(options.outputDir, pagePath(page)), renderPage(page), 'utf8')
    ),
  ]);
  return pages;
}

#!/usr/bin/env node
import * as path from 'path';
import { build } from './ssg';

export interface CliOptions {
  contentDir: string;
  outputDir: string;
}

export type ParseResult = CliOptions | 'help' | 'invalid';

export function printHelp(): void {
  console.log(`Usage: ssg build [options]

Generate a static site from Markdown files.

Options:
  --content <dir>  Directory containing Markdown content (default: ./content)
  --output <dir>   Directory to write the generated HTML (default: ./dist)
  --help, -h       Show this help message
`);
}

export function parseArgs(args: string[]): ParseResult {
  if (args.length === 0) {
    return 'invalid';
  }
  const subcommand = args[0];
  if (subcommand === '--help' || subcommand === '-h') {
    return 'help';
  }
  if (subcommand !== 'build') {
    return 'invalid';
  }
  const options: CliOptions = { contentDir: 'content', outputDir: 'dist' };
  for (let i = 1; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--help' || arg === '-h') {
      return 'help';
    }
    if (arg === '--content' || arg === '--output') {
      const value = args[i + 1];
      if (!value || value.startsWith('--')) {
        return 'invalid';
      }
      if (arg === '--content') {
        options.contentDir = value;
      } else {
        options.outputDir = value;
      }
      i += 1;
    } else {
      return 'invalid';
    }
  }
  return options;
}

async function main(): Promise<void> {
  const parsed = parseArgs(process.argv.slice(2));
  if (parsed === 'help') {
    printHelp();
    return;
  }
  if (parsed === 'invalid') {
    console.error('Invalid arguments. Run `ssg --help` for usage.');
    process.exitCode = 1;
    return;
  }
  try {
    const pages = await build(parsed);
    console.log(`Generated ${pages.length} page(s) in ${path.resolve(parsed.outputDir)}`);
  } catch (err) {
    console.error(`Build failed: ${(err as Error).message}`);
    process.exitCode = 1;
  }
}

if (require.main === module) {
  void main();
}

import { promises as fs } from 'fs';
import * as os from 'os';
import * as path from 'path';

import {
  build,
  escapeHtml,
  listMarkdownFiles,
  pagePath,
  parseMarkdownFile,
  renderIndex,
  renderPage,
} from '../src/ssg';
import { parseArgs, printHelp } from '../src/cli';
import type { Page } from '../src/types';

const FIXTURES = path.join(__dirname, 'fixtures');
const CONTENT_DIR = path.join(FIXTURES, 'content');

let tempRoot: string;
let outputDir: string;

beforeAll(async () => {
  tempRoot = await fs.mkdtemp(path.join(os.tmpdir(), 'ssg-test-'));
  outputDir = path.join(tempRoot, 'dist');
});

afterAll(async () => {
  await fs.rm(tempRoot, { recursive: true, force: true });
});

describe('listMarkdownFiles', () => {
  it('recursively finds markdown files sorted by path', async () => {
    const files = await listMarkdownFiles(CONTENT_DIR);
    const relative = files.map((file) => path.relative(CONTENT_DIR, file).replace(/\\/g, '/'));
    expect(relative).toEqual(['fixture-one.md', 'sub/fixture-two.md']);
  });
});

describe('parseMarkdownFile', () => {
  it('parses frontmatter fields and renders markdown to HTML', async () => {
    const page = await parseMarkdownFile(path.join(CONTENT_DIR, 'fixture-one.md'));
    expect(page.slug).toBe('fixture-one');
    expect(page.title).toBe('Fixture One');
    expect(page.date).toBe('2023-06-01');
    expect(page.tags).toEqual(['alpha', 'beta']);
    expect(page.html).toContain('<h1>Fixture One</h1>');
    expect(page.html).toContain('<strong>fixture</strong>');
  });

  it('parses tags given as a comma-separated string', async () => {
    const page = await parseMarkdownFile(path.join(CONTENT_DIR, 'sub', 'fixture-two.md'));
    expect(page.tags).toEqual(['gamma', 'delta']);
    expect(page.html).toContain('<a href="https://example.com">link</a>');
  });

  it('falls back to the filename for the title when frontmatter is missing', async () => {
    const page = await parseMarkdownFile(path.join(FIXTURES, 'raw.md'));
    expect(page.slug).toBe('raw');
    expect(page.title).toBe('Raw Title');
  });
});

describe('renderPage', () => {
  const page: Page = {
    slug: 'demo',
    title: 'Demo <Page>',
    date: '2024-03-04',
    tags: ['one', 'two'],
    content: 'Body',
    html: '<p>Body</p>',
  };

  it('produces a full HTML document with the title, date, and tags', () => {
    const html = renderPage(page);
    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('<title>Demo &lt;Page&gt;</title>');
    expect(html).toContain('<h1>Demo &lt;Page&gt;</h1>');
    expect(html).toContain('datetime="2024-03-04"');
    expect(html).toContain('<p>Body</p>');
    expect(html).toContain('<span class="tag">one</span>');
    expect(html).toContain('<a href="index.html">Home</a>');
  });
});

describe('renderIndex', () => {
  it('lists pages sorted by date descending with links', () => {
    const pages: Page[] = [
      {
        slug: 'a',
        title: 'A',
        date: '2024-01-01',
        tags: [],
        content: '',
        html: '',
      },
      {
        slug: 'b',
        title: 'B',
        date: '2025-01-01',
        tags: ['x'],
        content: '',
        html: '',
      },
      {
        slug: 'c',
        title: 'C',
        date: undefined,
        tags: [],
        content: '',
        html: '',
      },
    ];
    const html = renderIndex(pages);
    expect(html).toContain('<a href="a.html">A</a>');
    expect(html).toContain('<a href="b.html">B</a>');
    expect(html).toContain('<a href="c.html">C</a>');
    const indexB = html.indexOf('>B</a>');
    const indexA = html.indexOf('>A</a>');
    const indexC = html.indexOf('>C</a>');
    expect(indexB).toBeGreaterThan(-1);
    expect(indexB).toBeLessThan(indexA);
    expect(indexA).toBeLessThan(indexC);
    expect(html).toContain('x');
  });
});

describe('build', () => {
  it('writes index.html and one HTML file per page to the output directory', async () => {
    const pages = await build({ contentDir: CONTENT_DIR, outputDir });
    expect(pages).toHaveLength(2);

    const files = (await fs.readdir(outputDir)).sort();
    expect(files).toEqual(['fixture-one.html', 'fixture-two.html', 'index.html']);

    const index = await fs.readFile(path.join(outputDir, 'index.html'), 'utf8');
    expect(index).toContain('Fixture One');
    expect(index).toContain('Fixture Two');
    expect(index).toContain('fixture-one.html');

    const pageHtml = await fs.readFile(path.join(outputDir, 'fixture-two.html'), 'utf8');
    expect(pageHtml).toContain('<h1>Fixture Two</h1>');
    expect(pageHtml).toContain('<a href="https://example.com">link</a>');
  });
});

describe('parseArgs', () => {
  it('uses defaults for build', () => {
    expect(parseArgs(['build'])).toEqual({ contentDir: 'content', outputDir: 'dist' });
  });

  it('honors --content and --output', () => {
    expect(parseArgs(['build', '--content', 'src/posts', '--output', 'public'])).toEqual({
      contentDir: 'src/posts',
      outputDir: 'public',
    });
  });

  it('returns help for --help', () => {
    expect(parseArgs(['--help'])).toBe('help');
    expect(parseArgs(['build', '-h'])).toBe('help');
  });

  it('returns invalid for unknown subcommands or missing option values', () => {
    expect(parseArgs([])).toBe('invalid');
    expect(parseArgs(['serve'])).toBe('invalid');
    expect(parseArgs(['build', '--content'])).toBe('invalid');
    expect(parseArgs(['build', '--output', '--content', 'x'])).toBe('invalid');
  });
});

describe('utilities', () => {
  it('slugifies filenames with spaces, caps, and extensions', async () => {
    const file = path.join(FIXTURES, 'My Cool Post.md');
    await fs.writeFile(file, '# Hi\n');
    const page = await parseMarkdownFile(file);
    expect(page.slug).toBe('my-cool-post');
    expect(pagePath(page)).toBe('my-cool-post.html');
    await fs.unlink(file);
  });

  it('escapes HTML in titles and tag output', () => {
    expect(escapeHtml('<a href="x">&')).toBe('&lt;a href=&quot;x&quot;&gt;&amp;');
  });

  it('printHelp prints usage text', () => {
    const spy = jest.spyOn(console, 'log').mockImplementation(() => undefined);
    printHelp();
    expect(spy).toHaveBeenCalledWith(expect.stringContaining('ssg build'));
    spy.mockRestore();
  });
});

declare module 'gray-matter' {
  interface GrayMatterFile {
    data: Record<string, unknown>;
    content: string;
    excerpt?: string;
    orig: Buffer | string;
    language: string;
    matter: string;
    stringify(lang?: string): string;
  }

  interface GrayMatterOptions {
    excerpt?: boolean | string;
    excerpt_separator?: string;
    engines?: Record<string, unknown>;
    language?: string;
    delimiters?: string | [string, string];
  }

  function matter(
    input: string | Buffer,
    options?: GrayMatterOptions
  ): GrayMatterFile;

  namespace matter {
    function read(
      filepath: string,
      options?: GrayMatterOptions
    ): GrayMatterFile;
    function stringify(file: string, data: object, options?: GrayMatterOptions): string;
  }

  export = matter;
}

